arguments.command:
cd /tmp/vally-eval-trial-QjayjB && mkdir -p tests/CheckoutPricing.UnitTests/Checkout && cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier
{
    Gold,
}

public sealed class CalculatePayableTotal
{
    public decimal Handle(CustomerTier tier, decimal orderSubtotal) => orderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/GoldCustomerDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class GoldCustomerDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_00_subtotal_pays_95_00()
    {
        var total = new CalculatePayableTotal().Handle(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests --filter "FullyQualifiedName~GoldCustomerDiscountTests" --verbosity quiet 2>&1 | tail -20

